query Installation($key: ID!) {
  installation(key: $key) {
    key
    title
    description
    deleted
    created
    homepage
    type
    endpoints {
      type
      url
    }
    organization {
      key
      title
    }
    contacts {
      key
      type
      firstName
      lastName
      email
      phone
      homepage
      organization
      roles
      userId
    }

    dataset(limit: 0) {
      count
    }
  }
}
